// ===== inlined _shared/cors.ts =====
/**
 * CORS headers attached to EVERY response (success, failure, and preflight).
 * verify_jwt is disabled in config.toml so the OPTIONS preflight (which
 * carries no Authorization header) reaches the function; each function then
 * verifies the JWT itself via requireUser().
 */
export const corsHeaders: Record<string, string> = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, GET, OPTIONS",
  "Access-Control-Max-Age": "86400",
};

/** Standard response for the CORS preflight request. */
export function handleOptions(): Response {
  return new Response("ok", { status: 200, headers: corsHeaders });
}

// ===== inlined _shared/response.ts =====
/**
 * Uniform JSON envelope used by every edge function:
 *   success: { success: true,  data: <object>, error: null }
 *   failure: { success: false, data: null,     error: { code, message } }
 */

export interface ApiError {
  code: string;
  message: string;
}

export interface ApiEnvelope<T> {
  success: boolean;
  data: T | null;
  error: ApiError | null;
}

/** Structured error carrying an envelope code and an HTTP status. */
export class HttpError extends Error {
  readonly code: string;
  readonly status: number;

  constructor(code: string, message: string, status: number) {
    super(message);
    this.name = "HttpError";
    this.code = code;
    this.status = status;
  }
}

const jsonHeaders: Record<string, string> = {
  ...corsHeaders,
  "Content-Type": "application/json",
};

/** 200 success envelope. */
export function ok<T>(data: T): Response {
  const body: ApiEnvelope<T> = { success: true, data, error: null };
  return new Response(JSON.stringify(body), {
    status: 200,
    headers: jsonHeaders,
  });
}

/** Failure envelope with an appropriate HTTP status code. */
export function fail(code: string, message: string, status = 400): Response {
  const body: ApiEnvelope<never> = {
    success: false,
    data: null,
    error: { code, message },
  };
  return new Response(JSON.stringify(body), { status, headers: jsonHeaders });
}

/**
 * Convert any thrown value into a failure Response.
 * HttpError keeps its code/status; everything else becomes INTERNAL_ERROR
 * (logged server-side, never leaked to the client).
 */
export function failFromError(err: unknown, context: string): Response {
  if (err instanceof HttpError) {
    if (err.status >= 500) console.error(`[${context}]`, err.code, err.message);
    return fail(err.code, err.message, err.status);
  }
  console.error(`[${context}] unhandled error:`, err);
  return fail("INTERNAL_ERROR", "An unexpected error occurred", 500);
}

// ===== inlined _shared/supabase.ts =====
function requireEnv(name: string): string {
  const value = Deno.env.get(name);
  if (!value) {
    throw new HttpError("CONFIG_ERROR", `${name} is not configured`, 500);
  }
  return value;
}

/**
 * RLS-scoped client: anon key + the caller's Authorization header.
 * Every query runs as the calling user, so Row Level Security applies.
 */
export function createUserClient(req: Request): SupabaseClient {
  const url = requireEnv("SUPABASE_URL");
  const anonKey = requireEnv("SUPABASE_ANON_KEY");
  return createClient(url, anonKey, {
    global: {
      headers: { Authorization: req.headers.get("Authorization") ?? "" },
    },
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

/**
 * Service-role client: BYPASSES Row Level Security.
 * Use ONLY where the spec requires it (admin verification/actions, storage
 * downloads that were already authorized in code, profile lookups by email).
 */
export function createServiceClient(): SupabaseClient {
  const url = requireEnv("SUPABASE_URL");
  const serviceKey = requireEnv("SUPABASE_SERVICE_ROLE_KEY");
  return createClient(url, serviceKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

interface PostgrestLikeError {
  message: string;
  code?: string;
}

interface PostgrestLikeResult<T> {
  data: T | null;
  error: PostgrestLikeError | null;
}

/**
 * Unwrap a supabase-js result, mapping common PostgREST failures onto the
 * envelope error codes.
 */
export function unwrap<T>(result: PostgrestLikeResult<T>, what: string): T {
  if (result.error) {
    if (result.error.code === "42501") {
      throw new HttpError("FORBIDDEN", `Not allowed: ${what}`, 403);
    }
    if (result.error.code === "PGRST116") {
      throw new HttpError("NOT_FOUND", `${what}: not found`, 404);
    }
    throw new HttpError("DB_ERROR", `${what}: ${result.error.message}`, 500);
  }
  return result.data as T;
}

// ===== inlined _shared/auth.ts =====
export type UserRole = "candidate" | "interviewer" | "admin";
export type UserStatus = "active" | "suspended";

export interface Profile {
  id: string;
  full_name: string;
  email: string;
  avatar_url: string | null;
  role: UserRole;
  status: UserStatus;
  experience_years: number | null;
}

export interface AuthContext {
  user: User;
  userClient: SupabaseClient;
}

/**
 * Verify the caller's JWT (config.toml sets verify_jwt = false so that the
 * CORS preflight succeeds; THIS is the mandatory auth gate for every request).
 * Returns the verified user plus an RLS-scoped client.
 */
export async function requireUser(req: Request): Promise<AuthContext> {
  const authHeader = req.headers.get("Authorization") ?? "";
  const token = authHeader.replace(/^Bearer\s+/i, "").trim();
  if (!token) {
    throw new HttpError("UNAUTHORIZED", "Missing Authorization bearer token", 401);
  }

  const userClient = createUserClient(req);
  const { data, error } = await userClient.auth.getUser(token);
  if (error || !data?.user) {
    throw new HttpError("UNAUTHORIZED", "Invalid or expired token", 401);
  }
  return { user: data.user, userClient };
}

/**
 * Load the caller's profile and enforce that the account is active.
 * Throws 404 PROFILE_NOT_FOUND / 403 ACCOUNT_SUSPENDED.
 */
export async function getProfile(
  client: SupabaseClient,
  userId: string,
): Promise<Profile> {
  const { data, error } = await client
    .from("profiles")
    .select("id, full_name, email, avatar_url, role, status, experience_years")
    .eq("id", userId)
    .maybeSingle();

  if (error) {
    throw new HttpError("DB_ERROR", `Failed to load profile: ${error.message}`, 500);
  }
  if (!data) {
    throw new HttpError("PROFILE_NOT_FOUND", "No profile exists for this user", 404);
  }
  const profile = data as Profile;
  if (profile.status !== "active") {
    throw new HttpError("ACCOUNT_SUSPENDED", "This account is suspended", 403);
  }
  return profile;
}

/** Throw 403 FORBIDDEN unless the profile has one of the allowed roles. */
export function requireRole(profile: Profile, roles: readonly UserRole[]): void {
  if (!roles.includes(profile.role)) {
    throw new HttpError(
      "FORBIDDEN",
      `This action requires one of the roles: ${roles.join(", ")}`,
      403,
    );
  }
}

// ===== inlined _shared/rateLimit.ts =====
/**
 * In-memory sliding-window rate limiter.
 *
 * LIMITATION: state lives in a module-level Map, i.e. it is PER EDGE-RUNTIME
 * INSTANCE. Supabase may run several isolates (and cold-starts reset the map),
 * so the effective limit is approximate. In production, back this with a
 * durable shared store (Redis/Upstash, or a Postgres table keyed by
 * user+function+window) for a hard guarantee. It still stops the common case:
 * a single client hammering one warm instance.
 *
 * Defaults: 30 requests/min per user per function; AI-backed functions use
 * 15/min. Callers return 429 RATE_LIMITED when this returns false.
 */

const WINDOW_DEFAULT_MS = 60_000;
const LIMIT_DEFAULT = 30;

/** Per-AI-function default (heavier upstream cost). */
export const AI_RATE_LIMIT = 15;

const buckets = new Map<string, number[]>();

/**
 * Returns true when the call is allowed, false when the key exceeded
 * `limit` calls within the sliding `windowMs` window.
 */
export function checkRateLimit(
  key: string,
  limit: number = LIMIT_DEFAULT,
  windowMs: number = WINDOW_DEFAULT_MS,
): boolean {
  const now = Date.now();
  const cutoff = now - windowMs;
  const timestamps = (buckets.get(key) ?? []).filter((t) => t > cutoff);

  if (timestamps.length >= limit) {
    buckets.set(key, timestamps);
    return false;
  }

  timestamps.push(now);
  buckets.set(key, timestamps);

  // Opportunistic cleanup so the map cannot grow unbounded on a warm instance.
  if (buckets.size > 10_000) {
    for (const [k, ts] of buckets) {
      if (ts.every((t) => t <= cutoff)) buckets.delete(k);
    }
  }
  return true;
}

// ===== inlined _shared/validate.ts =====
/**
 * Tiny request validators. Every failure throws
 * HttpError("VALIDATION_ERROR", ..., 400).
 */

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

function invalid(message: string): HttpError {
  return new HttpError("VALIDATION_ERROR", message, 400);
}

/** Parse the JSON request body into a plain object. */
export async function readJsonBody(
  req: Request,
): Promise<Record<string, unknown>> {
  let parsed: unknown;
  try {
    parsed = await req.json();
  } catch {
    throw invalid("Request body must be valid JSON");
  }
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw invalid("Request body must be a JSON object");
  }
  return parsed as Record<string, unknown>;
}

export interface StringOptions {
  min?: number;
  max?: number;
}

export function requireString(
  value: unknown,
  field: string,
  opts: StringOptions = {},
): string {
  if (typeof value !== "string") throw invalid(`${field} must be a string`);
  const trimmed = value.trim();
  const min = opts.min ?? 1;
  if (trimmed.length < min) {
    throw invalid(`${field} must be at least ${min} character(s)`);
  }
  if (opts.max !== undefined && trimmed.length > opts.max) {
    throw invalid(`${field} must be at most ${opts.max} characters`);
  }
  return trimmed;
}

export function optionalString(
  value: unknown,
  field: string,
  opts: StringOptions = {},
): string | undefined {
  if (value === undefined || value === null || value === "") return undefined;
  return requireString(value, field, opts);
}

export function requireNumberInRange(
  value: unknown,
  field: string,
  min: number,
  max: number,
): number {
  const num = typeof value === "string" && value.trim() !== ""
    ? Number(value)
    : value;
  if (typeof num !== "number" || !Number.isFinite(num)) {
    throw invalid(`${field} must be a number`);
  }
  if (num < min || num > max) {
    throw invalid(`${field} must be between ${min} and ${max}`);
  }
  return num;
}

export function optionalNumberInRange(
  value: unknown,
  field: string,
  min: number,
  max: number,
): number | undefined {
  if (value === undefined || value === null || value === "") return undefined;
  return requireNumberInRange(value, field, min, max);
}

export function requireEnum<T extends string>(
  value: unknown,
  field: string,
  allowed: readonly T[],
): T {
  if (typeof value !== "string" || !allowed.includes(value as T)) {
    throw invalid(`${field} must be one of: ${allowed.join(", ")}`);
  }
  return value as T;
}

export function optionalEnum<T extends string>(
  value: unknown,
  field: string,
  allowed: readonly T[],
): T | undefined {
  if (value === undefined || value === null || value === "") return undefined;
  return requireEnum(value, field, allowed);
}

export function requireUuid(value: unknown, field: string): string {
  if (typeof value !== "string" || !UUID_RE.test(value)) {
    throw invalid(`${field} must be a valid UUID`);
  }
  return value.toLowerCase();
}

export function optionalUuid(value: unknown, field: string): string | undefined {
  if (value === undefined || value === null || value === "") return undefined;
  return requireUuid(value, field);
}

export function optionalBoolean(
  value: unknown,
  field: string,
): boolean | undefined {
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "boolean") throw invalid(`${field} must be a boolean`);
  return value;
}

/** Missing value -> []; present value must be an array of strings. */
export function optionalStringArray(
  value: unknown,
  field: string,
  maxItems = 100,
  maxItemLength = 20_000,
): string[] {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) throw invalid(`${field} must be an array of strings`);
  if (value.length > maxItems) {
    throw invalid(`${field} must contain at most ${maxItems} items`);
  }
  return value.map((item, i) => {
    if (typeof item !== "string") {
      throw invalid(`${field}[${i}] must be a string`);
    }
    return item.length > maxItemLength ? item.slice(0, maxItemLength) : item;
  });
}

export function requireEmail(value: unknown, field: string): string {
  const email = requireString(value, field, { min: 5, max: 320 });
  if (!EMAIL_RE.test(email)) throw invalid(`${field} must be a valid email address`);
  return email;
}

export function isUuid(value: string): boolean {
  return UUID_RE.test(value);
}

// ===== inlined _shared/audit.ts =====
/**
 * Best-effort audit logging - never throws, never fails the request.
 * With a user client the audit_logs INSERT policy requires
 * user_id === auth.uid(); with the service client any user_id is accepted.
 */
export async function logAudit(
  client: SupabaseClient,
  userId: string | null,
  action: string,
  resourceType?: string | null,
  resourceId?: string | null,
  metadata?: Record<string, unknown>,
): Promise<void> {
  try {
    const { error } = await client.from("audit_logs").insert({
      user_id: userId,
      action,
      resource_type: resourceType ?? null,
      resource_id: resourceId ?? null,
      metadata: metadata ?? {},
    });
    if (error) {
      console.error(`logAudit(${action}) insert failed:`, error.message);
    }
  } catch (err) {
    console.error(`logAudit(${action}) threw:`, err);
  }
}

