export function reportSystemPrompt(): string {
  return `You write a professional executive narrative (150-250 words, plain text, 2-3 paragraphs) for an interview assessment report. Base it strictly on the structured report data provided; do not invent facts, and keep the tone neutral and professional.

${SAFETY_RULES}

Respond ONLY with one JSON object, no prose, exactly this shape:
{"narrative": string}`;
}

export function reportUserPrompt(p: { report: unknown }): string {
  return `Structured interview report data:\n${truncate(JSON.stringify(p.report), 12000)}`;
}

// ---------------------------------------------------------------------------
// Robust parsing + normalization
// ---------------------------------------------------------------------------

/** Parse a JSON object out of a model reply (tolerates fences/extra prose). */
export function parseJsonObject(raw: string): Record<string, unknown> {
  let text = raw.trim();
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced) text = fenced[1].trim();

  const candidates = [text];
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start >= 0 && end > start) candidates.push(text.slice(start, end + 1));

  for (const candidate of candidates) {
    try {
      const value: unknown = JSON.parse(candidate);
      if (value !== null && typeof value === "object" && !Array.isArray(value)) {
        return value as Record<string, unknown>;
      }
    } catch {
      // try next candidate
    }
  }
  throw new Error("AI response did not contain a parseable JSON object");
}

/** Coerce to a number clamped to [0, 100]; fallback (default 50) if invalid. */
export function clampScore(value: unknown, fallback = 50): number {
  const num = typeof value === "string" ? Number(value) : value;
  if (typeof num !== "number" || !Number.isFinite(num)) return fallback;
  return Math.min(100, Math.max(0, Math.round(num * 10) / 10));
}

function optionalNumber(
  value: unknown,
  min: number,
  max: number,
): number | null {
  const num = typeof value === "string" ? Number(value) : value;
  if (typeof num !== "number" || !Number.isFinite(num)) return null;
  return Math.min(max, Math.max(min, num));
}

function toStringArray(value: unknown, maxItems: number): string[] {
  if (!Array.isArray(value)) return [];
  return value
    .filter((item): item is string => typeof item === "string" && item.trim() !== "")
    .slice(0, maxItems)
    .map((item) => item.trim());
}

const QUESTION_TYPES = [
  "behavioral",
  "hr",
  "technical",
  "situational",
  "coding",
  "mcq",
] as const;
const DIFFICULTIES = ["easy", "medium", "hard", "expert"] as const;

export function normalizeGeneratedQuestion(
  obj: Record<string, unknown>,
  p: GenerateQuestionParams,
): GeneratedQuestion {
  const question = typeof obj.question === "string" ? obj.question.trim() : "";
  if (!question) throw new Error("AI provider did not return a question");

  const fallbackType = p.interviewType === "mixed" ? "technical" : p.interviewType;
  const questionType =
    typeof obj.question_type === "string" &&
      (QUESTION_TYPES as readonly string[]).includes(obj.question_type)
      ? obj.question_type
      : fallbackType;

  const difficulty =
    typeof obj.difficulty === "string" &&
      (DIFFICULTIES as readonly string[]).includes(obj.difficulty)
      ? obj.difficulty
      : p.difficulty;

  const category =
    typeof obj.category === "string" && obj.category.trim() !== ""
      ? obj.category.trim()
      : (p.category ?? p.role);

  const timeLimit = optionalNumber(obj.time_limit_seconds, 30, 900);

  return {
    question,
    category,
    question_type: questionType,
    expected_topics: toStringArray(obj.expected_topics, 8),
    time_limit_seconds: Math.round(timeLimit ?? 180),
    is_follow_up: obj.is_follow_up === true,
    difficulty,
  };
}

export function normalizeAnswerAnalysis(
  obj: Record<string, unknown>,
): AnswerAnalysis {
  const fillers = optionalNumber(obj.filler_word_count, 0, 10_000);
  return {
    relevance: clampScore(obj.relevance),
    technical_accuracy: clampScore(obj.technical_accuracy),
    communication: clampScore(obj.communication),
    clarity: clampScore(obj.clarity),
    structure: clampScore(obj.structure),
    confidence_indicator: clampScore(obj.confidence_indicator),
    speaking_pace: optionalNumber(obj.speaking_pace, 0, 400),
    filler_word_count: fillers === null ? null : Math.round(fillers),
    strengths: toStringArray(obj.strengths, 5),
    weaknesses: toStringArray(obj.weaknesses, 5),
    recommendations: toStringArray(obj.recommendations, 5),
    summary: typeof obj.summary === "string" ? obj.summary.trim() : "",
  };
}

const RECOMMENDATIONS = ["strong_hire", "hire", "consider", "no_hire"] as const;

export function normalizeResultSummary(
  obj: Record<string, unknown>,
): ResultSummary {
  const recommendation =
    typeof obj.recommendation === "string" &&
      (RECOMMENDATIONS as readonly string[]).includes(obj.recommendation)
      ? (obj.recommendation as Recommendation)
      : "consider";
  return {
    summary: typeof obj.summary === "string" ? obj.summary.trim() : "",
    strengths: toStringArray(obj.strengths, 6),
    weaknesses: toStringArray(obj.weaknesses, 6),
    recommendation,
  };
}

// ===== inlined _shared/ai/openai.ts =====
/**
 * Base URL is configurable so any OpenAI-compatible provider works —
 * including free tiers: Groq (https://api.groq.com/openai/v1), Google
 * Gemini (https://generativelanguage.googleapis.com/v1beta/openai),
 * OpenRouter (https://openrouter.ai/api/v1). Defaults to OpenAI itself.
 */
export function openAIBaseUrl(): string {
  return (Deno.env.get("OPENAI_BASE_URL") ?? "https://api.openai.com/v1").replace(/\/+$/, "");
}

const OPENAI_REQUEST_TIMEOUT_MS = 60_000;

interface OpenAIChatResponse {
  choices?: Array<{ message?: { content?: string | null } }>;
}

export class OpenAIProvider implements AIProvider {
  readonly name = "openai";
  private readonly apiKey: string;
  private readonly model: string;
  private readonly chatUrl: string;

  constructor(apiKey: string) {
    this.apiKey = apiKey;
    this.model = Deno.env.get("AI_MODEL") ?? "gpt-4o-mini";
    this.chatUrl = `${openAIBaseUrl()}/chat/completions`;
  }

  private async chatJson(
    system: string,
    user: string,
    temperature: number,
  ): Promise<Record<string, unknown>> {
    const response = await fetch(this.chatUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${this.apiKey}`,
      },
      body: JSON.stringify({
        model: this.model,
        temperature,
        response_format: { type: "json_object" },
        messages: [
          { role: "system", content: system },
          { role: "user", content: user },
        ],
      }),
      signal: AbortSignal.timeout(OPENAI_REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      const detail = (await response.text()).slice(0, 500);
      throw new Error(`OpenAI API error ${response.status}: ${detail}`);
    }

    const payload = (await response.json()) as OpenAIChatResponse;
    const content = payload.choices?.[0]?.message?.content;
    if (!content) throw new Error("OpenAI returned an empty completion");
    return parseJsonObject(content);
  }

  async generateQuestion(p: GenerateQuestionParams): Promise<GeneratedQuestion> {
    const obj = await this.chatJson(
      questionSystemPrompt(),
      questionUserPrompt(p, false),
      0.7,
    );
    return normalizeGeneratedQuestion(obj, p);
  }

  async generateFollowUp(p: GenerateQuestionParams): Promise<GeneratedQuestion> {
    const obj = await this.chatJson(
      questionSystemPrompt(),
      questionUserPrompt(p, true),
      0.7,
    );
    return { ...normalizeGeneratedQuestion(obj, p), is_follow_up: true };
  }

  async analyzeAnswer(p: AnalyzeAnswerParams): Promise<AnswerAnalysis> {
    const obj = await this.chatJson(
      analysisSystemPrompt(),
      analysisUserPrompt(p),
      0.2,
    );
    return normalizeAnswerAnalysis(obj);
  }

  async generateSummary(p: SummaryParams): Promise<ResultSummary> {
    const obj = await this.chatJson(
      summarySystemPrompt(),
      summaryUserPrompt(p),
      0.3,
    );
    return normalizeResultSummary(obj);
  }

  async generateReport(p: { report: unknown }): Promise<string> {
    const obj = await this.chatJson(
      reportSystemPrompt(),
      reportUserPrompt(p),
      0.4,
    );
    return typeof obj.narrative === "string" && obj.narrative.trim() !== ""
      ? obj.narrative.trim()
      : JSON.stringify(obj);
  }
}

// ===== inlined _shared/ai/anthropic.ts =====
const ANTHROPIC_MESSAGES_URL = "https://api.anthropic.com/v1/messages";
const ANTHROPIC_VERSION = "2023-06-01";
const ANTHROPIC_REQUEST_TIMEOUT_MS = 60_000;

interface AnthropicContentBlock {
  type: string;
  text?: string;
}

interface AnthropicMessagesResponse {
  content?: AnthropicContentBlock[];
}

export class AnthropicProvider implements AIProvider {
  readonly name = "anthropic";
  private readonly apiKey: string;
  private readonly model: string;

  constructor(apiKey: string) {
    this.apiKey = apiKey;
    this.model = Deno.env.get("AI_MODEL") ?? "claude-sonnet-5";
  }

  private async completeJson(
    system: string,
    user: string,
    temperature: number,
    maxTokens = 2000,
  ): Promise<Record<string, unknown>> {
    const response = await fetch(ANTHROPIC_MESSAGES_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": this.apiKey,
        "anthropic-version": ANTHROPIC_VERSION,
      },
      body: JSON.stringify({
        model: this.model,
        max_tokens: maxTokens,
        temperature,
        system,
        messages: [{ role: "user", content: user }],
      }),
      signal: AbortSignal.timeout(ANTHROPIC_REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      const detail = (await response.text()).slice(0, 500);
      throw new Error(`Anthropic API error ${response.status}: ${detail}`);
    }

    const payload = (await response.json()) as AnthropicMessagesResponse;
    const text = payload.content
      ?.filter((block) => block.type === "text" && typeof block.text === "string")
      .map((block) => block.text as string)
      .join("\n");
    if (!text) throw new Error("Anthropic returned an empty completion");
    return parseJsonObject(text);
  }

  async generateQuestion(p: GenerateQuestionParams): Promise<GeneratedQuestion> {
    const obj = await this.completeJson(
      questionSystemPrompt(),
      questionUserPrompt(p, false),
      0.7,
    );
    return normalizeGeneratedQuestion(obj, p);
  }

  async generateFollowUp(p: GenerateQuestionParams): Promise<GeneratedQuestion> {
    const obj = await this.completeJson(
      questionSystemPrompt(),
      questionUserPrompt(p, true),
      0.7,
    );
    return { ...normalizeGeneratedQuestion(obj, p), is_follow_up: true };
  }

  async analyzeAnswer(p: AnalyzeAnswerParams): Promise<AnswerAnalysis> {
    const obj = await this.completeJson(
      analysisSystemPrompt(),
      analysisUserPrompt(p),
      0.2,
    );
    return normalizeAnswerAnalysis(obj);
  }

  async generateSummary(p: SummaryParams): Promise<ResultSummary> {
    const obj = await this.completeJson(
      summarySystemPrompt(),
      summaryUserPrompt(p),
      0.3,
    );
    return normalizeResultSummary(obj);
  }

  async generateReport(p: { report: unknown }): Promise<string> {
    const obj = await this.completeJson(
      reportSystemPrompt(),
      reportUserPrompt(p),
      0.4,
    );
    return typeof obj.narrative === "string" && obj.narrative.trim() !== ""
      ? obj.narrative.trim()
      : JSON.stringify(obj);
  }
}

// ===== inlined _shared/ai/index.ts =====
/**
 * Resolve the configured AI provider:
 *  - AI_PROVIDER=openai|anthropic selects explicitly (needs its key);
 *  - otherwise auto-detect by whichever of OPENAI_API_KEY / ANTHROPIC_API_KEY
 *    exists (OpenAI wins when both are set);
 *  - null when nothing is configured. Callers respond with a
 *    503 AI_NOT_CONFIGURED envelope in that case.
 */
export function getAIProvider(): AIProvider | null {
  const preference = (Deno.env.get("AI_PROVIDER") ?? "").trim().toLowerCase();
  const openaiKey = Deno.env.get("OPENAI_API_KEY");
  const anthropicKey = Deno.env.get("ANTHROPIC_API_KEY");

  if (preference === "openai") {
    return openaiKey ? new OpenAIProvider(openaiKey) : null;
  }
  if (preference === "anthropic") {
    return anthropicKey ? new AnthropicProvider(anthropicKey) : null;
  }
  if (openaiKey) return new OpenAIProvider(openaiKey);
  if (anthropicKey) return new AnthropicProvider(anthropicKey);
  return null;
}

// ===== function: generate-question =====
/**
 * POST generate-question
 * Generates the next adaptive interview question (or a follow-up ~30% of the
 * time after question 2 when the previous answer has substance).
 */
Deno.serve(async (req: Request): Promise<Response> => {
  if (req.method === "OPTIONS") return handleOptions();

  try {
    if (req.method !== "POST") {
      throw new HttpError("METHOD_NOT_ALLOWED", "Use POST", 405);
    }

    const { user, userClient } = await requireUser(req);
    await getProfile(userClient, user.id); // enforces active account

    if (!checkRateLimit(`generate-question:${user.id}`, AI_RATE_LIMIT)) {
      throw new HttpError("RATE_LIMITED", "Too many requests - try again in a minute", 429);
    }

    const body = await readJsonBody(req);
    const role = requireString(body.role, "role", { min: 2, max: 120 });
    const interviewType = requireEnum(body.interview_type, "interview_type", [
      "hr",
      "technical",
      "behavioral",
      "mixed",
    ] as const);
    const difficulty = requireEnum(body.difficulty, "difficulty", [
      "easy",
      "medium",
      "hard",
      "expert",
    ] as const);
    const questionNumber = requireNumberInRange(body.question_number, "question_number", 1, 100);
    const totalQuestions = requireNumberInRange(body.total_questions, "total_questions", 1, 100);
    const previousQuestions = optionalStringArray(body.previous_questions, "previous_questions", 100, 2000);
    const previousAnswers = optionalStringArray(body.previous_answers, "previous_answers", 100, 20_000);
    const experienceYears = optionalNumberInRange(body.experience_years, "experience_years", 0, 60);
    const category = optionalString(body.category, "category", { max: 120 });
    const resumeSummary = optionalString(body.resume_summary, "resume_summary", { max: 6000 });
    const interviewId = optionalUuid(body.interview_id, "interview_id");

    // If tied to an interview, the RLS-scoped select proves the caller is a
    // participant (creator/candidate/admin) - non-participants see no row.
    if (interviewId) {
      const { data: interview, error } = await userClient
        .from("interviews")
        .select("id")
        .eq("id", interviewId)
        .maybeSingle();
      if (error) throw new HttpError("DB_ERROR", error.message, 500);
      if (!interview) {
        throw new HttpError("NOT_FOUND", "Interview not found or you are not a participant", 404);
      }
    }

    const provider = getAIProvider();
    if (!provider) {
      throw new HttpError(
        "AI_NOT_CONFIGURED",
        "No AI provider is configured. Set OPENAI_API_KEY or ANTHROPIC_API_KEY (and optionally AI_PROVIDER).",
        503,
      );
    }

    const params: GenerateQuestionParams = {
      role,
      experienceYears,
      interviewType,
      difficulty,
      category,
      questionNumber,
      totalQuestions,
      previousQuestions,
      previousAnswers,
      resumeSummary,
    };

    // Adaptive behavior: first question is always an introduction (handled in
    // the prompt); after Q2, ~30% of questions become follow-ups when the last
    // answer has enough substance to probe.
    const lastAnswer = previousAnswers[previousAnswers.length - 1] ?? "";
    const askFollowUp =
      questionNumber > 2 &&
      lastAnswer.trim().split(/\s+/).filter(Boolean).length >= 12 &&
      Math.random() < 0.3;

    const question = askFollowUp
      ? await provider.generateFollowUp(params)
      : await provider.generateQuestion(params);

    return ok(question);
  } catch (err) {
    return failFromError(err, "generate-question");
  }
});
